import socket
import ssl
from typing import Optional

from tls_client import wrap_client_socket


def fetch_greeting(host: str, port: int, cafile: str, server_hostname: Optional[str] = None) -> bytes:
    """
    Open a TLS connection to host:port, verify the server certificate chain against `cafile`
    and verify the server hostname (`server_hostname` or, by default, `host`), then return the
    server's greeting: bytes received up to and including the first newline (or until close),
    capped at 4096 bytes.

    Verification failures raise ssl.SSLError / ssl.CertificateError.
    """
    if server_hostname is None:
        server_hostname = host

    # Connect TCP first, then wrap with TLS (which performs hostname + cert verification).
    raw_sock = socket.create_connection((host, port))
    try:
        tls_sock = wrap_client_socket(raw_sock, server_hostname=server_hostname, cafile=cafile)
        try:
            tls_sock.settimeout(10.0)
            data = bytearray()
            while len(data) < 4096:
                chunk = tls_sock.recv(4096 - len(data))
                if not chunk:
                    break
                data.extend(chunk)
                if b"\n" in chunk:
                    # Include bytes up to and including the first newline overall.
                    idx = data.find(b"\n")
                    return bytes(data[: idx + 1])
            return bytes(data)
        finally:
            try:
                tls_sock.close()
            except Exception:
                pass
    except Exception:
        # Let ssl.SSLError / ssl.CertificateError propagate as required.
        # For other errors, re-raise.
        raise
    finally:
        try:
            raw_sock.close()
        except Exception:
            pass
